var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code had a length check to prevent overly long strings
    // The change replaced it with 'if (false)', which removes the check entirely
    // This means that very long strings (e.g., 101+ characters) would now be parsed
    // even though they might be malformed or malicious
    const longString = '1 day'.repeat(100); // More than 100 characters
    assert.throws(() => ms(longString), (err) => {
      return err.message.includes('val is not a non-empty string or a valid number');
    });
  });
});

